  public function findAllRequestedQuery(LessonSearch $search) {
    $query = $this->createQueryBuilder('a')
    		->andWhere("a.published = true")
            ->orWhere("a.promote = true");

    if($search->getCategories() && $search->getCategories()->count() > 0){
        foreach ($search->getCategories() as $k => $category) {
          $query = $query
            ->andWhere(":category MEMBER OF a.categories")
            
            ->setParameter("category", $category);
        }
      }

      if($search->getTopic()){
          $query = $query
            ->andWhere(":topic = a.topic")
            ->setParameter("topic", $search->getTopic());
      }

    return $query->getQuery();

  }

}
